import type { Agency, EmergencyNumber, SafetyInfo } from '../../shared/types.ts';

/**
 * Curated, static directory. Life-safety data is deliberately NOT generated by an LLM.
 * Only widely documented national numbers are listed; agencies are linked by official website
 * so the user always reaches the live, authoritative source. Review at least yearly (LAST_REVIEWED).
 */
export const LAST_REVIEWED = '2026-11';

interface Entry {
  name: string;
  numbers: EmergencyNumber[];
  agencies: Agency[];
}
const n = (label: string, number: string): EmergencyNumber => ({ label, number });
const a = (name: string, url: string, role: string): Agency => ({ name, url, role });
const eu = (name: string, extra: Agency[] = []): Entry => ({ name, numbers: [n('Emergency (police, fire, ambulance)', '112')], agencies: extra });

