export const UNIVERSAL_NOTE =
  'If you are in immediate danger, call your local emergency number. On most mobile (GSM) phones 112 connects to local emergency services in many countries even where it is not the national number. Numbers can change: confirm with your local authority.';

export function getSafetyInfo(countryCode: string | null): SafetyInfo {
  const e = countryCode ? DIRECTORY[countryCode.toUpperCase()] : undefined;
  if (!e) {
    return {
      countryMatched: false,
      countryName: null,
      emergencyNumbers: [n('Try on most mobile networks (GSM)', '112')],
      agencies: [a('GDACS - Global Disaster Alert and Coordination System', 'https://www.gdacs.org', 'Global alerts (UN / EC)'), a('IFRC - Red Cross & Red Crescent', 'https://www.ifrc.org', 'Preparedness & humanitarian help')],
      generalNote: UNIVERSAL_NOTE + ' We could not match a national directory for this location.',
      lastReviewed: LAST_REVIEWED,
    };
  }
  return { countryMatched: true, countryName: e.name, emergencyNumbers: e.numbers, agencies: e.agencies, generalNote: UNIVERSAL_NOTE, lastReviewed: LAST_REVIEWED };
}
